CustomField.formula:
/*Gitlab#19517*/
/*This value population is only for Legal country = 'India' else for other countries it will be as null*/
IF(
   ISPICKVAL(QTB_Legal_Entity_Country__c, 'India'),
   IF(
        BillingCountry != 'India',
        'EXPWP',
        IF(
            QTB_SEZ_Customer__c = FALSE,
            IF(
                (QTB_Tax_Registration__c != 'URP') && (NOT(ISNULL(QTB_Tax_Registration__c) || ISBLANK(QTB_Tax_Registration__c))),
                'B2B',
                'B2C'
            ),
            IF(
                ISPICKVAL(SBQQ__TaxExempt__c, 'Yes'),
                'SEZWOP',
                'SEZWP'
            )
        )
    ),
	/*This is to populate 'B2G' for Greece if Contract number is not null - Gitlab #29135 else for all other countries it will be null*/
    IF(
        ISPICKVAL(QTB_Legal_Entity_Country__c, 'Greece') && (NOT(ISBLANK(QTB_ContractNumber__c))), 
        'B2G',

        /*This is to populate 'B2C' for Turkey if Tax registration is > 10 characters - Gitlab #34161 else for all other countries it will be null*/
        IF(
		   ISPICKVAL(QTB_Legal_Entity_Country__c, 'Turkey') && (LEN(QTB_Tax_Registration__c) > 10),
            'B2C',
            null
        )
    )
)
